			byte b = readByte();
			if (b == 0)
				return false;
			if (b == 1)
				return true;
			throw new IOException("Invalid boolean value: " + b);
		}

		/* @Override */
		public byte readByte()
    {
			if (serialDataPosition >= serialDataLen) {
				throw new EOFException();
			}
			return serialData[serialDataPosition++];
		}

		/* @Override */
		public int readUnsignedByte()
    {
			if (serialDataPosition >= serialDataLen) {
